// generated by nlang -> js
'use strict';

let sky = document.getElementById("sky");

let ctx = sky.getContext("2d");

let W = 960;

let H = 560;

let stars = [];

let i = 0;

while ((i < 300)) {
    stars.push([(Math.random() * W), (Math.random() * H), Math.random()]);
    (i += 1);
}

let blot = [];

i = 0;

while ((i < 44)) {
    blot.push([Math.random(), Math.random(), ((Math.random() * 0.55000000000000004) + 0.12), Math.random()]);
    (i += 1);
}

let phase = 0.0;

let playing = false;

let ac = 0;

let master = 0;

let analyser = 0;

let btn = document.getElementById("playbtn");

let st = document.getElementById("status");

let vol = document.getElementById("vol");

let scale = [220.0, 261.63, 293.66000000000003, 349.23000000000002, 392.0, 440.0];

function pluck() {
    if (!playing) {
    return 0;
}
    let o = ac.createOscillator();
    o.type = "triangle";
    let k = Math.floor((Math.random() * 6.0));
    o.frequency.value = scale[(k + 1) - 1];
    let g = ac.createGain();
    let t = ac.currentTime;
    g.gain.setValueAtTime(0.0, t);
    g.gain.linearRampToValueAtTime(0.14000000000000001, (t + 0.029999999999999999));
    g.gain.exponentialRampToValueAtTime(0.001, (t + 1.6000000000000001));
    o.connect(g);
    g.connect(master);
    o.start(t);
    o.stop((t + 1.7));
}

function ensure_audio() {
    if ((ac !== 0)) {
    return 0;
}
    ac = new AudioContext();
    master = ac.createGain();
    master.gain.value = (parseFloat(vol.value) / 100.0);
    master.connect(ac.destination);
    analyser = ac.createAnalyser();
    analyser.fftSize = 128;
    master.connect(analyser);
    let o1 = ac.createOscillator();
    o1.type = "sawtooth";
    o1.frequency.value = 55.0;
    let o2 = ac.createOscillator();
    o2.type = "sine";
    o2.frequency.value = 110.0;
    let fl = ac.createBiquadFilter();
    fl.type = "lowpass";
    fl.frequency.value = 240.0;
    fl.Q.value = 6.0;
    let g1 = ac.createGain();
    g1.gain.value = 0.070000000000000007;
    o1.connect(fl);
    o2.connect(fl);
    fl.connect(g1);
    g1.connect(master);
    o1.start();
    o2.start();
    let lfo = ac.createOscillator();
    lfo.frequency.value = 0.070000000000000007;
    let lg = ac.createGain();
    lg.gain.value = 90.0;
    lfo.connect(lg);
    lg.connect(fl.frequency);
    lfo.start();
    setInterval(pluck, 1100);
}

function draw() {
    ctx.fillStyle = "#020206";
    ctx.fillRect(0, 0, W, H);
    let n = 0;
    for (const s of stars) {
    let tw = (0.25 + (0.75 * Math.abs(Math.sin(((phase * 1.5) + (n * 1.7))))));
    ctx.fillStyle = (("rgba(215,228,255," + (tw * s[3 - 1])) + ")");
    if ((s[3 - 1] > 0.75)) {
    ctx.fillRect(s[1 - 1], s[2 - 1], 2, 2);
} else {
    ctx.fillRect(s[1 - 1], s[2 - 1], 1, 1);
}
    (n += 1);
}
    let cx = (W * 0.59999999999999998);
    let cy = (H * 0.5);
    let R = 160.0;
    let level = 0.0;
    if (playing) {
    if ((analyser !== 0)) {
    let arr = new Uint8Array(analyser.frequencyBinCount);
    analyser.getByteFrequencyData(arr);
    let sum = 0.0;
    for (const b of arr) {
    (sum += b);
}
    level = ((sum / analyser.frequencyBinCount) / 255.0);
}
}
    let glow = ctx.createRadialGradient(cx, cy, (R * 0.5), cx, cy, (R * (2.0 + (level * 1.3999999999999999))));
    glow.addColorStop(0.0, (("rgba(255,110,50," + (0.12 + (level * 0.40000000000000002))) + ")"));
    glow.addColorStop(1.0, "rgba(255,80,30,0)");
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, W, H);
    let pg = ctx.createRadialGradient((cx - (R * 0.34999999999999998)), (cy - (R * 0.40000000000000002)), (R * 0.080000000000000002), cx, cy, R);
    pg.addColorStop(0.0, "#ff9a60");
    pg.addColorStop(0.40000000000000002, "#e05a22");
    pg.addColorStop(0.78000000000000003, "#8c2008");
    pg.addColorStop(1.0, "#3d0d03");
    ctx.fillStyle = pg;
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0.0, (Math.PI * 2.0));
    ctx.fill();
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0.0, (Math.PI * 2.0));
    ctx.clip();
    for (const b of blot) {
    let uu = (b[1 - 1] + (phase * 0.059999999999999998));
    (uu -= Math.floor(uu));
    let bx = ((cx - R) + ((uu * R) * 2.0));
    let by = ((cy - (R * 0.75)) + ((b[2 - 1] * R) * 1.5));
    let br = (b[3 - 1] * 34.0);
    ctx.fillStyle = (("rgba(50,12,4," + (0.17999999999999999 + (b[4 - 1] * 0.29999999999999999))) + ")");
    ctx.beginPath();
    ctx.ellipse(bx, by, br, (br * 0.45000000000000001), 0.0, 0.0, (Math.PI * 2.0));
    ctx.fill();
}
    ctx.fillStyle = "rgba(255,238,224,0.5)";
    ctx.beginPath();
    ctx.ellipse(cx, (cy - (R * 0.90000000000000002)), (R * 0.45000000000000001), (R * 0.14000000000000001), 0.0, 0.0, (Math.PI * 2.0));
    ctx.fill();
    let sh = ctx.createLinearGradient((cx + (R * 0.20000000000000001)), cy, (cx + R), cy);
    sh.addColorStop(0.0, "rgba(0,0,8,0)");
    sh.addColorStop(1.0, "rgba(1,0,6,0.9)");
    ctx.fillStyle = sh;
    ctx.fillRect((cx + (R * 0.20000000000000001)), (cy - R), (R * 0.80000000000000004), (R * 2.0));
    ctx.restore();
    let px = (cx + (Math.cos((phase * 0.80000000000000004)) * (R + 80.0)));
    let py = (cy + ((Math.sin((phase * 0.80000000000000004)) * (R + 80.0)) * 0.45000000000000001));
    ctx.fillStyle = "#8a6a55";
    ctx.beginPath();
    ctx.arc(px, py, 3.0, 0.0, (Math.PI * 2.0));
    ctx.fill();
    (phase += 0.0080000000000000002);
    requestAnimationFrame(draw);
}

function onplay() {
    ensure_audio();
    playing = !playing;
    if (playing) {
    ac.resume();
    btn.textContent = "STOP";
    st.textContent = "playing // ambient";
} else {
    ac.suspend();
    btn.textContent = "PLAY";
    st.textContent = "engine idle";
}
}

function onvol() {
    if ((ac !== 0)) {
    master.gain.value = (parseFloat(vol.value) / 100.0);
}
}

btn.addEventListener("click", onplay);

vol.addEventListener("input", onvol);

requestAnimationFrame(draw);

